import * as THREE from 'three';
export function studioEnvironment(renderer){const room=new THREE.Scene();room.background=new THREE.Color('#343c44');const shell=new THREE.Mesh(new THREE.BoxGeometry(20,20,20),new THREE.MeshBasicMaterial({color:'#48535b',side:THREE.BackSide}));room.add(shell);for(const [position,size,color] of [[[-4,5,3],[4,7,1],'#f6eddc'],[[5,2,1],[2,8,1],'#b6cadb'],[[0,7,-4],[7,2,1],'#ffffff'],[[-3,-2,7],[6,5,1],'#e7ebe5']]){const p=new THREE.Mesh(new THREE.PlaneGeometry(size[0],size[1]),new THREE.MeshBasicMaterial({color,side:THREE.DoubleSide}));p.position.set(...position);p.lookAt(0,0,0);room.add(p);}const pmrem=new THREE.PMREMGenerator(renderer),target=pmrem.fromScene(room,.06);pmrem.dispose();room.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});return target;}
